class MathUtils:
    """Static helpers for elementary arithmetic operations."""
    @staticmethod
    def gcd(a: int, b: int) -> int:
        """Return the greatest common divisor of a and b.

        Examples:
            >>> MathUtils.gcd(48, 18)
            6
            >>> MathUtils.gcd(7, 13)
            1
            >>> MathUtils.gcd(0, 5)
            5
        """
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("a and b must be integers")
        if a < 0 or b < 0:
            raise ValueError("gcd is undefined for negative inputs")
        while b:
            a, b = b, a % b
        return abs(a)

