                raise ValueError("rank must be 1..10, A, J, Q, K") from exc
            if not (2 <= value <= 10):
                raise ValueError("rank must be 1..10, A, J, Q, K")
            self._rank_value = value
            self.rank = str(value)

    def __len__(self) -> int:
        return self._rank_value

    def __repr__(self) -> str:
