class CycleGenerator:
    """An iterable that cycles through its items indefinitely.

    Examples:
        >>> list(CycleGenerator([1, 2, 3]).take(7))
        [1, 2, 3, 1, 2, 3, 1]
        >>> list(CycleGenerator([]).take(3))
        []
    """
    def __init__(self, items: List[Any]) -> None:
        self._items: List[Any] = list(items)

    def __iter__(self) -> Iterator[Any]:
        if not self._items:
            return
        i = 0
        while True:
            yield self._items[i]
            i = (i + 1) % len(self._items)

    def take(self, n: int) -> Iterator[Any]:
        if n < 0:
            raise ValueError("n must be non-negative")
        it = iter(self)
        for _ in range(n):
            try:
                yield next(it)
            except StopIteration:
                return

